//! Cargo-driven `mfplat.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is mfplat-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", None),
        o => panic!("mfplat-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:wine", "engine:uuid", "sdk/lib/dmoguids/libdmoguids.a", "sdk/lib/mfuuid/libmfuuid.a", "sdk/lib/strmiids/libstrmiids.a", "engine:c:dxguid", "engine:oldnames", "import:bcrypt", "import:advapi32", "import:ole32", "import:oleaut32", "import:propsys", "import:rtworkq", "import:user32", "import:shlwapi", "import:kernelbase", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust"],
        "x86_64" => &["body", "engine:wine", "engine:uuid", "sdk/lib/dmoguids/libdmoguids.a", "sdk/lib/mfuuid/libmfuuid.a", "sdk/lib/strmiids/libstrmiids.a", "engine:c:dxguid", "engine:oldnames", "import:bcrypt", "import:advapi32", "import:ole32", "import:oleaut32", "import:propsys", "import:rtworkq", "import:user32", "import:shlwapi", "import:kernelbase", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust"],
        "aarch64" => &["body", "engine:wine", "engine:uuid", "sdk/lib/dmoguids/libdmoguids.a", "sdk/lib/mfuuid/libmfuuid.a", "sdk/lib/strmiids/libstrmiids.a", "engine:c:dxguid", "engine:oldnames", "import:bcrypt", "import:advapi32", "import:ole32", "import:oleaut32", "import:propsys", "import:rtworkq", "import:user32", "import:shlwapi", "import:kernelbase", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=+sse,+sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("mfplat-rust")
        .spec2def("dll/win32/mfplat/mfplat.spec", "mfplat.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/bcrypt/bcrypt.spec", "bcrypt.dll", "bcrypt")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/propsys/propsys.spec", "propsys.dll", "propsys")
        .import_lib("dll/win32/rtworkq/rtworkq.spec", "rtworkq.dll", "rtworkq")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/kernelbase/kernelbase.spec", "kernelbase.dll", "kernelbase")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
